const TZ = 'America/New_York';
const OPEN = 8, CLOSE = 18;
const i = $input.first().json;
const DUR = { 'exterior hand wash': 60, 'maintenance': 60, 'interior deep clean': 120, 'leather & fabric care': 90, 'leather and fabric care': 90, 'wheels & engine bay': 90, 'wheels and engine bay': 90, 'full detail': 240, 'paint correction': 360, 'ceramic coating': 480, 'ceramic pro': 480 };
const svc = String(i.service || 'Full Detail').trim().toLowerCase();
const key = Object.keys(DUR).find(k => svc.includes(k)) || 'full detail';
const vt = String(i.vehicleType || '').toLowerCase();
const big = /suv|truck|van|pickup|classic|4x4|minivan/.test(vt);
const base = DUR[key];
const duration = Math.min(Math.ceil((big && base < 480 ? base * 1.25 : base) / 30) * 30, (CLOSE - OPEN) * 60);
let day = i.date ? DateTime.fromISO(String(i.date), { zone: TZ }) : (i.afterTime ? DateTime.fromISO(String(i.afterTime), { zone: TZ }) : DateTime.now().setZone(TZ).plus({ days: 1 }));
if (!day.isValid) return [{ json: { valid: false, message: 'I could not understand that date. Please give a date like 2026-11-06.' } }];
day = day.startOf('day');
const closed = day.weekday === 7;
const open = day.set({ hour: OPEN });
const close = day.set({ hour: CLOSE });
return [{ json: { valid: true, closed, service: key, vehicleType: i.vehicleType || '', durationMinutes: duration, date: day.toISODate(), dayName: day.toFormat('cccc'), timeMin: open.toISO(), timeMax: close.toISO() } }];

const TZ = 'America/New_York';
const w = $('Build Business-Hours Window').first().json;
if (!w.valid) return [{ json: { success: false, message: w.message } }];
if (w.closed) return [{ json: { success: true, date: w.date, dayName: w.dayName, slots: [], message: 'Hercules Detailing is closed on Sundays. We are open Monday to Saturday, 8 AM to 6 PM.' } }];
const busy = $input.all().map(e => e.json).filter(e => e && e.start && e.status !== 'cancelled' && e.transparency !== 'transparent').map(e => ({ s: DateTime.fromISO(e.start.dateTime || e.start.date, { zone: TZ }), e: DateTime.fromISO(e.end.dateTime || e.end.date, { zone: TZ }) }));
const open = DateTime.fromISO(w.timeMin, { zone: TZ });
const close = DateTime.fromISO(w.timeMax, { zone: TZ });
const now = DateTime.now().setZone(TZ).plus({ minutes: 60 });
const slots = [];
for (let t = open; t.plus({ minutes: w.durationMinutes }) <= close; t = t.plus({ minutes: 30 })) {
  const end = t.plus({ minutes: w.durationMinutes });
  if (t < now) continue;
  if (busy.some(b => t < b.e && end > b.s)) continue;
  slots.push({ start: t.toISO(), end: end.toISO(), label: t.toFormat('h:mm a') });
}
const preview = slots.slice(0, 6).map(s => s.label).join(', ');
return [{ json: { success: true, date: w.date, dayName: w.dayName, service: w.service, durationMinutes: w.durationMinutes, slots, message: slots.length ? `${w.dayName} ${w.date}: ${slots.length} start times available for a ${w.durationMinutes}-minute ${w.service}. Earliest: ${preview}.` : `No openings long enough for a ${w.durationMinutes}-minute ${w.service} on ${w.dayName} ${w.date}. Offer another day.` } }];
